package main

import (
	"fmt"
	"math"
)

func main() {
	var n int
	if _, err := fmt.Scan(&n); err != nil {
		return
	}

	// labels are 1..n
	label := make([]int, n+1)
	for i := 1; i <= n; i++ {
		label[i] = i
	}

	// dp[i][j] = min weight for polygon from vertex i to j (inclusive)
	dp := make([][]int, n+2)
	for i := range dp {
		dp[i] = make([]int, n+2)
	}

	// initialize for length 2 (just an edge) -> weight 0
	for i := 1; i <= n-1; i++ {
		dp[i][i+1] = 0
	}
	dp[n][1] = 0 // not used in linear DP

	// we use linear DP on vertices 1..n
	// for a convex polygon, we can fix vertex 1 and do DP on chain 1..n
	// but careful: the polygon is cyclic. Standard approach: DP on intervals [i, j] where j-i >= 2
	// We'll compute dp[i][j] for 1 <= i < j <= n
	// For intervals of length >= 3
	for length := 3; length <= n; length++ {
		for i := 1; i+length-1 <= n; i++ {
			j := i + length - 1
			dp[i][j] = math.MaxInt64
			for k := i + 1; k < j; k++ {
				// triangle (i, k, j)
				val := dp[i][k] + dp[k][j] + label[i]*label[k]*label[j]
				if val < dp[i][j] {
					dp[i][j] = val
				}
			}
		}
	}

	fmt.Println(dp[1][n])
}
